class Node {
  int data;
  Node next;
  Node (int data) {
    this.data = data;
    this.next = null;
  }
}

class LinkedList {
  Node head;

  public void insert(int data) {
    Node newNode = new Node(data);
    if (head == null) {
      head = newNode;
    } 
    else {
      Node current = head;
      while (current.next != null) {
        current = current.next;
      }
      current.next = newNode;
    }
  }
}

